export type CompareRow = {
  id: string;
  label: string;
  a: string;
  b: string;
  c: string;
};

export type CompareLabels = {
  caption: string;
  feature: string;
  a: string;
  b: string;
  c: string;
  yes: string;
  no: string;
};
